export const preSuccessionPhases = seriesArcDossiers.flatMap((dossier) => dossier.phases.map((item, index) => ({
  ...item,
  arcId: dossier.id,
  arcTitle: dossier.title,
  phaseOrder: index + 1,
  phaseCount: dossier.phases.length,
})));

export const getSeriesArcDossier = (arcId) => seriesArcDossiers.find((dossier) => dossier.id === arcId);
export const getSeriesPhaseByChapter = (number) => preSuccessionPhases.find((item) => number >= item.range[0] && number <= item.range[1]);

export const phaseCoverageNumbers = preSuccessionPhases.flatMap((item) => Array.from({ length: item.range[1] - item.range[0] + 1 }, (_, index) => item.range[0] + index));
